#include "channelcard.h"

#include <QSignalBlocker>
#include <QTimer>
#include <algorithm>

#include "ui_channelcard.h"   // generated by uic from channelcard.ui

ChannelCard::ChannelCard(iwp::DeviceModel *model, int channel, QWidget *parent)
    : QGroupBox(parent), m_model(model), m_channel(channel),
      m_prefix(QStringLiteral("ch%1_").arg(channel)), ui(std::make_unique<Ui::ChannelCard>())
{
    ui->setupUi(this);
    setTitle(tr("CH%1").arg(channel));

    // The setpoint is sent when the user pauses, not on every step of the arrow keys.
    auto makeTimer = [this](const char *command, QDoubleSpinBox *spin) {
        auto *timer = new QTimer(this);
        timer->setSingleShot(true);
        timer->setInterval(200);
        connect(timer, &QTimer::timeout, this, [this, command, spin] {
            m_model->sendCommand(QString::fromLatin1(command),
                                 QVariantMap{{"ch", m_channel}, {"value", spin->value()}});
        });
        connect(spin, &QDoubleSpinBox::valueChanged, timer, qOverload<>(&QTimer::start));
        return timer;
    };
    m_voltTimer = makeTimer("setVoltage", ui->voltSpin);
    m_currTimer = makeTimer("setCurrent", ui->currSpin);

    connect(ui->channelButton, &QPushButton::clicked, this, [this](bool on) {
        m_model->sendCommand(QStringLiteral("channelOn"), QVariantMap{{"ch", m_channel}, {"on", on}});
    });

    connect(m_model, &iwp::DeviceModel::valueChanged, this,
            [this](const QString &key, const QVariant &) {
                if (key == QLatin1String("master") || key.startsWith(m_prefix))
                    refresh();
            });
    connect(m_model, &iwp::DeviceModel::staleChanged, this,
            [this](const QString &key, bool) {
                if (key.startsWith(m_prefix))
                    refresh();
            });
    connect(m_model, &iwp::DeviceModel::statusChanged, this, [this] { updateEnabled(); });

    refresh();
    updateEnabled();
}

ChannelCard::~ChannelCard() = default;

QVariant ChannelCard::value(const char *name) const
{
    return m_model->value(m_prefix + QLatin1String(name));
}

bool ChannelCard::isStale(const char *name) const
{
    return m_model->isStale(m_prefix + QLatin1String(name));
}

void ChannelCard::refresh()
{
    // measured values
    const double v = value("v_meas").toDouble();
    const double i = value("i_meas").toDouble();
    ui->voltLcd->display(QString::number(v, 'f', 3));
    ui->currLcd->display(QString::number(i, 'f', 3));
    ui->voltLcd->setEnabled(!isStale("v_meas"));
    ui->currLcd->setEnabled(!isStale("i_meas"));
    ui->powerLabel->setText(tr("%1 W").arg(v * i, 0, 'f', 2));

    // CV: the instrument holds the voltage, CC: it is limiting the current
    const QString mode = value("mode").toString();
    const char *color = mode == QLatin1String("CV") ? "#2e7d32"
                        : mode == QLatin1String("CC") ? "#c62828" : "#757575";
    ui->modeLabel->setText(mode.isEmpty() ? QStringLiteral("-")
                           : mode == QLatin1String("OFF") ? tr("OFF") : mode);
    ui->modeLabel->setStyleSheet(QStringLiteral("font-weight: bold; color: %1;").arg(QLatin1String(color)));

    // load against the current limit
    const double limit = value("i_set").toDouble();
    ui->loadBar->setValue(limit > 0.0 ? int(std::clamp(i / limit * 100.0, 0.0, 100.0)) : 0);
    ui->loadLabel->setText(tr("%1 / %2 A").arg(i, 0, 'f', 3).arg(limit, 0, 'f', 3));

    // do not fight the user while they are editing a setpoint
    if (!m_voltTimer->isActive() && !ui->voltSpin->hasFocus()) {
        QSignalBlocker blocker(ui->voltSpin);
        ui->voltSpin->setValue(value("v_set").toDouble());
    }
    if (!m_currTimer->isActive() && !ui->currSpin->hasFocus()) {
        QSignalBlocker blocker(ui->currSpin);
        ui->currSpin->setValue(value("i_set").toDouble());
    }

    // protection
    auto setLabel = [](QLabel *label, const QString &text, const char *color) {
        label->setText(text);
        label->setStyleSheet(QStringLiteral("color: %1;").arg(QLatin1String(color)));
    };
    if (!value("fuse_on").toBool())
        setLabel(ui->fuseLabel, tr("Fuse: %1").arg(tr("off")), "#757575");
    else if (value("fuse_trip").toBool())
        setLabel(ui->fuseLabel, tr("Fuse: %1").arg(tr("TRIPPED")), "#c62828");
    else
        setLabel(ui->fuseLabel, tr("Fuse: %1").arg(tr("ok")), "#2e7d32");
    if (value("ovp_trip").toBool())
        setLabel(ui->ovpLabel, tr("OVP: %1").arg(tr("TRIPPED")), "#c62828");
    else
        setLabel(ui->ovpLabel, tr("OVP: %1").arg(tr("ok")), "#2e7d32");

    // the channel is armed, but nothing comes out until the master output is on
    const bool armed = value("sel").toBool();
    ui->channelButton->setChecked(armed);
    ui->hintLabel->setVisible(armed && !m_model->value(QStringLiteral("master")).toBool());
}

void ChannelCard::updateEnabled()
{
    const bool running = m_model->status() == iwp::DeviceModel::Status::Running;
    ui->voltSpin->setEnabled(running);
    ui->currSpin->setEnabled(running);
    ui->channelButton->setEnabled(running);
}
